{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is neither reported nor explicitly ruled out."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "EFPA sections 9.3 and 9.7 are reinterpreted as consistency across repeated AI evaluations. Repeatability evidence is insufficient, corresponding to 0 rather than demonstrated inadequacy. Under 9.6, inter-rater reliability is inapplicable to the stated exact-grid scoring without judgement."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated evaluations."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "No repeated-run findings support stability; this does not establish instability."
        }
      ],
      "instrument_review": "EFPA 9.3 and 9.7 are reinterpreted for repeated AI evaluations. The explicit absence of repetitions leaves repeatability unassessable: 0 for insufficient evidence, not 1 for demonstrated poor consistency. Exact-grid scoring makes judgement-based inter-rater reliability under 9.6 inapplicable."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The passage reports repetitions under the same specified conditions and their score variation."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The two-percentage-point range meets the report's stated stability definition."
        }
      ],
      "instrument_review": "Under EFPA 9.7, repeated-run ranges provide alternative precision evidence; 9.3 supplies a related retest perspective. Stability is supported for this system and these conditions. The report's stability rule is not an EFPA quality anchor, so it does not alone justify a 2–4 rating or broader reliability claims."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated evaluations and score variation are explicitly reported."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The reported range exceeds the stated maximum of two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 permits assessing repeated-run variation as alternative precision evidence, with 9.3 providing a retest analogy. Unlike missing evidence, these results demonstrate failure of the stated stability criterion. This is an adverse precision finding for the specified comparison, without establishing an overall instrument rating."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions supply no evidence of repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The documentation addition provides no repeated-run findings supporting stability."
        }
      ],
      "instrument_review": "Installation guidance is relevant to EFPA 6.3.8 on software instructions, but does not establish software robustness under 7.1.1 or precision under 9.3/9.7. Reinterpreted AI repeatability remains insufficiently evidenced, warranting 0 for that evidence rather than a finding of inadequate stability."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A achieved the higher observed performance on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The passage supplies no evidence establishing general intelligence across domains."
        }
      ],
      "instrument_review": "EFPA 10.1 and 10.5 tie interpretation to the measured content and intended use. Treating AI systems as the assessed units, the observed comparison fits the narrow stated purpose; generalisation across domains is unsupported. Section 8.3.2.2 permits a norms exception for a sole raw-score ranking purpose, but does not establish broader validity or precision."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The observed results support A's higher performance on these puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a broad intended use does not supply evidence that the scores establish it."
        }
      ],
      "instrument_review": "EFPA 10.1, 10.3 and 10.5 require evidence supporting the intended score interpretation. Reinterpreting the assessed units as AI systems, the broad selection purpose exceeds the supplied grid-only evidence. Validity for that purpose remains insufficiently evidenced; this does not prove that A lacks greater general intelligence."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone supply no demonstrated connection to improved workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports higher correctness with A in the studied workshop; the reported difference interval is wholly positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved correctness does not establish an improvement in the unmeasured safety outcome."
        }
      ],
      "instrument_review": "EFPA 10.3.1.6 addresses the randomized intervention evidence; 10.3.2 addresses correctness as a relevant external criterion. The later trial strengthens evidence for the stated workshop use, but supplies no test-score–outcome relationship or safety evidence. Human inspectors are trial participants, while the benchmark compares AI assistance. EFPA human-examinee qualifications and debriefing questions are not directly applicable to the AI systems."
    }
  ],
  "closing_note": "The probe instructions are clear. The request for the complete EFPA model is read together with the explicit allowance for brief relevant-section reviews rather than full forms. Human testing concepts are reinterpreted only where stated; human sensory, motor and personal-demographic requirements do not directly apply to AI systems. Supported, Contradicted and Not established are evidence labels, not EFPA ratings. Missing evidence does not demonstrate poor quality, and no aggregate quality score is calculated. Instrument attribution: EFPA Test Review Model 2025, version 5.0, supplied extraction, CC BY-SA 4.0, https://www.efpa.eu/; this application does not imply EFPA endorsement."
}
